    // Use a map to store the last timestamp printed for each message
    Map<String, Integer> lastPrinted = new HashMap<>();

    // Check if this message has been printed in the same timestamp
    if (lastPrinted.containsKey(message)) {
        int lastTimestamp = lastPrinted.get(message);
        // If it was printed in the same timestamp, do not print
        if (lastTimestamp == timestamp) {
            return false;
        }
    }

    // Store the new timestamp for this message
    lastPrinted.put(message, timestamp);

    // Print the message
    return true;
}

