        return;
    }
    int remaining = descriptor.length();
    int index = 0;
    while (remaining > 0) {
        char c = descriptor.charAt(index);
        switch (c) {
            case 'V':
            case 'Z':
            case 'B':
            case 'S':
            case 'C':
            case 'I':
            case 'J':
            case 'F':
                index++;
                remaining--;
                break out;
            case 'D':
                index += 2;
                remaining -= 2;
                break out;
            case '[':
                int dim = index + 1;
                while (dim < remaining && descriptor.charAt(dim) == '[') {
                    dim++;
                }
                index = dim;
                remaining = remaining - dim;
                break;
            case 'L':
                int end = descriptor.indexOf(';', index);
                if (end < 0) {
                    index = remaining;
                    remaining = 0;
                    break out;
                }
                index = end + 1;
                remaining = remaining - index;
                break out;
            default:
                throw new IllegalArgumentException("Invalid descriptor character: " + c);
        }
    }

    out: {
        // The loop above already exited the while
    }
}

