protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return new DefaultWeightedPath<>(graph, 0.0);
    }

    List<E> edgePath = new ArrayList<>(tour);
    List<V> vertexPath = new ArrayList<>();

    // Find the start vertex: the vertex that appears exactly once (degree 1 in the path)
    Map<V, List<E>> vertexToEdges = new HashMap<>();
    for (E edge : edgePath) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        vertexToEdges.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        vertexToEdges.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    // Find a vertex with exactly one incident edge in the tour (an endpoint of the path)
    V start = null;
    for (Map.Entry<V, List<E>> entry : vertexToEdges.entrySet()) {
        if (entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }

    // If no vertex has degree 1, all vertices have degree 2 (circular tour), pick any vertex
    if (start == null) {
        start = edgePath.get(0).getSource();
    }

    vertexPath.add(start);
    E currentEdge = vertexToEdges.get(start).get(0);
    V currentVertex = start;

    // Build the path by traversing the tour
    while (true) {
        V nextVertex = graph.getIncidentVertex(currentVertex, currentEdge);
        vertexPath.add(nextVertex);
        currentVertex = nextVertex;

        // Find the next edge to follow
        List<E> edgesAtCurrentVertex = vertexToEdges.get(currentVertex);
        if (edgesAtCurrentVertex.size() > 1) {
            E otherEdge = edgesAtCurrentVertex.get(0) == currentEdge ? edgesAtCurrentVertex.get(1) : edgesAtCurrentVertex.get(0);
            currentEdge = otherEdge;
        }

        // Check if we've completed the tour
        if (vertexPath.size() == edgePath.size() + 1) {
            break;
        }
    }

    // Calculate total weight of the path
    double totalWeight = 0.0;
    for (E edge : edgePath) {
        totalWeight += graph.getEdgeWeight(edge);
    }

    return new DefaultWeightedPath<>(graph, totalWeight);
}

