    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return null;
    }

    // Find a starting node: an edge must exist, get its source
    E startEdge = tour.iterator().next();
    V start = graph.getEdgeSource(startEdge);
    if (start == null) {
        throw new IllegalArgumentException("Edge " + startEdge + " has no source vertex");
    }

    // Track visited edges to avoid cycles
    Set<E> visitedEdges = new HashSet<>(tour);

    // Track visited vertices
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    vertices.add(start);

    V current = start;
    while (!visitedEdges.isEmpty()) {
        // Find an unvisited edge from current vertex
        E nextEdge = null;
        for (E edge : visitedEdges) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            if (source != null && target != null) {
                if (source.equals(current)) {
                    nextEdge = edge;
                    break;
                }
                if (target.equals(current)) {
                    nextEdge = edge;
                    break;
                }
            }
        }

        if (nextEdge == null) {
            throw new IllegalArgumentException("Unable to continue path from vertex " + current);
        }

        edges.add(nextEdge);
        visitedEdges.remove(nextEdge);

        V source = graph.getEdgeSource(nextEdge);
        V target = graph.getEdgeTarget(nextEdge);

        if (source.equals(current)) {
            current = target;
        } else {
            current = source;
        }

        if (current == null) {
            throw new IllegalArgumentException("Edge " + nextEdge + " leads to null vertex");
        }

        vertices.add(current);
    }

    // Check if it's a tour (circuit): start and end at the same vertex
    if (!vertices.get(0).equals(vertices.get(vertices.size() - 1))) {
        // It's a path, not a tour, but still return it
    }

    return new DefaultDirectedPath<V,E>(graph, vertices, edges);
}

