private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || vertices.isEmpty()) {
        return true; // An empty set of vertices vacuously induces a complete graph
    }
    int size = vertices.size();
    if (size <= 1) {
        return true; // A single vertex or no vertices is trivially a clique
    }
    // For each pair of distinct vertices in the set, check if there is an edge between them
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue; // Skip self-loops, we only care about distinct pairs
            }
            // Check if there is an edge from v1 to v2
            if (!graph.getOutgoingNeighbourhood(v1).contains(v2)) {
                return false;
            }
        }
    }
    return true;
}

