public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }

    List<PathSegmentImpl> segments = new ArrayList<>();

    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }

    // If the path is absolute (starts with '/'), ignore the leading '/'
    int start = 0;
    if (rawPath.startsWith("/")) {
        start = 1;
    }

    if (start >= rawPath.length()) {
        return segments;
    }

    // Split the path into segments based on '/'
    int i = start;
    int length = rawPath.length();

    while (i < length) {
        // Find the next '/'
        int j = rawPath.indexOf('/', i);
        if (j == -1) {
            j = length;
        }

        String segment = rawPath.substring(i, j);
        if (!segment.isEmpty()) {
            String decodedSegment = segment;
            if (decode) {
                try {
                    decodedSegment = java.net.URLDecoder.decode(segment, "UTF-8");
                } catch (java.io.UnsupportedEncodingException e) {
                    // UTF-8 is always supported, so this is a fallback
                    throw new RuntimeException("Encoding error while decoding path segment", e);
                }
            }
            segments.add(new PathSegmentImpl(decodedSegment));
        }

        i = j + 1;
    }

    return segments;
}

