                    out[outIndex] = 'u';
                    outIndex++;
                    strIndex += 4;
                    continue;
                }
            } else {
                // Read as many unicode chars as possible
                // Unknown
                throw new IllegalArgumentException("Unexpected end of input: escaped unicode char");
            }
