public Action inspect(AtmosphereResource r) {
    // If the resource is suspended, skip further processing
    if (r.isSuspended()) {
        return Action.CONTINUE;
    }

    // Check if the resource supports polling or streaming transport
    Transport transport = r.transport();
    if (transport == null) {
        return Action.CONTINUE;
    }

    // Suspend the resource automatically based on transport type
    switch (transport) {
        case WEBSOCKET:
        case STREAMING:
        case POLLING:
        case XHR_STREAMING:
        case XHR2:
            r.suspend(0L, true);
            break;
        default:
            // For other transports, no automatic suspension
            break;
    }

    return Action.CONTINUE;
}

