        String line;
        ThreadSnapshot currentSnapshot = null;
        Map<String, Thread> currentThreads = null;

        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            if (line.startsWith("timestamp=")) {
                // finished on a new timestamp
                if (currentSnapshot != null && currentThreads != null) {
                    currentSnapshot.setThreads(new ArrayList<>(currentThreads.values()));
                    if (isWithinTimeRange(currentSnapshot.getTimestamp(), timeRanges)) {
                        snapshots.add(currentSnapshot);
                    }
                }
                long timestamp;
                try {
                    timestamp = Long.parseLong(line.substring("timestamp=".length()));
                } catch (NumberFormatException e) {
                    throw new IOException("Invalid timestamp format: " + line, e);
                }
                currentSnapshot = new ThreadSnapshot();
                currentSnapshot.setTimestamp(timestamp);
                currentThreads = new LinkedHashMap<>();
            } else if (line.startsWith("thread=") && currentSnapshot != null) {
                // format: thread=<id>:<name>
                String rest = line.substring("thread=".length());
                int colonIndex = rest.indexOf(':');
                if (colonIndex == -1) {
                    continue;
                }
                String threadId = rest.substring(0, colonIndex);
                String threadName = rest.substring(colonIndex + 1);
                Thread thread = new Thread();
                thread.setId(threadId);
                thread.setName(threadName);
                currentThreads.put(threadId, thread);
