                // assume the current thread is the last one added
                if (!currentThreads.isEmpty()) {
                    var entrySet = new ArrayList<>(currentThreads.entrySet());
                    Thread lastThread = entrySet.get(entrySet.size() - 1).getValue();
                    if (lastThread.getStack() == null) {
                        lastThread.setStack(new ArrayList<>());
                    }
                    lastThread.getStack().add(content);
                }
            }
        }

        if (currentSnapshot != null && currentThreads != null) {
