    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must not be negative");
    }

    // Handle null array: write null bytes (zeros)
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            put((byte) 0);
        }
        return this;
    }

    // Validate bounds
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset out of bounds: " + byteOffset);
    }
    if (byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
    }

    // Copy bytes
    for (int i = 0; i < byteLength; i++) {
        put(byteArrayValue[byteOffset + i]);
    }

    return this;
}

