public long readRawVarint64() throws IOException {
    int tmpByte;
    int shift = 0;
    long value = 0;
    while (true) {
        tmpByte = read();
        if (tmpByte == -1) {
            throw new IOException("Unexpected end of stream.");
        }
        value |= (long) (tmpByte & 0x7F) << shift;
        if ((tmpByte & 0x80) == 0) {
            return value;
        }
        if (shift >= 35) {
            throw new IOException("Varint too large.");
        }
        shift += 7;
    }
}

